<?php $methods=query("SELECT * FROM shipping_methods WHERE deleted_at IS NULL".(deliveryTypesReady()?" AND delivery_type='courier'":'')." ORDER BY active DESC,name")->fetchAll();$selected=(int)($_POST['delivery_id']??$o['planned_delivery_id']??0);?>
<h2>1. Priprema dostave</h2><p class="field-help">Odaberite način dostave i sačuvajte uslove prije štampanja. Ova radnja ne mijenja status, lager ni iznos kupčeve narudžbe.</p>
<?php if($methods):startForm('delivery_prepare',(int)$o['id']);?><div data-shipment-plan><label for="delivery_id">Način dostave</label><select id="delivery_id" name="delivery_id" required data-delivery-choice><option value="">Odaberite dostavu</option><?php foreach($methods as $d):?><option value="<?=$d['id']?>" <?=$selected===(int)$d['id']?'selected':''?> data-courier="<?=e($d['courier_name']?:$d['name'])?>" data-cost="<?=e($d['cost'])?>" data-terms="<?=e($d['terms'])?>" data-payer="<?=e($d['payer'])?>"><?=e($d['name'])?><?=$d['active']?'':' (interno)'?></option><?php endforeach;?></select><?php field('courier_name','Kurirska služba / izvršilac',$_POST['courier_name']??$o['courier_name']??'');field('delivery_cost','Dogovoreni trošak kurira KM',$_POST['delivery_cost']??$o['planned_delivery_cost']??'0.00');selectField('delivery_payer','Uslovi plaćanja dostave',deliveryPayers(),$_POST['delivery_payer']??$o['planned_delivery_payer']??'customer');textField('delivery_terms','Dogovoreni uslovi / rok / napomene',$_POST['delivery_terms']??$o['planned_delivery_terms']??'');field('tracking_number','Broj pošiljke (opcionalno)',$_POST['tracking_number']??$o['tracking_number']??'','text',false);field('note','Obrazloženje pripreme / izmjene');?><button>Sačuvaj pripremu dostave</button></div></form><noscript><p>Unesite kurira, trošak i uslove ručno prema odabranom načinu dostave.</p><ul><?php foreach($methods as $d):?><li><?=e($d['name'])?>: <?=e($d['courier_name']?:$d['name'])?> · <?=money((float)$d['cost'])?> · <?=e(deliveryPayers()[$d['payer']])?> · <?=e($d['terms'])?></li><?php endforeach;?></ul></noscript><?php else:?><p>Prvo dodajte način dostave u odjeljku Dostava.</p><?php endif;?>
<hr><h2>2. Potvrda predaje kuriru</h2><p class="field-help">Nakon sačuvane pripreme odštampajte list, predajte paket kuriru i potvrdite slanje.</p><?php if($o['planned_delivery_id']):startForm('status',(int)$o['id']);?><input type="hidden" name="status" value="shipped"><input type="hidden" name="courier_name" value="<?=e($o['courier_name'])?>"><?php textField('dispatch_note','Obavezno obrazloženje / dokument predaje kuriru');?><button>Potvrdi slanje i razduži lager</button></form><?php else:?><p>Potvrda slanja dostupna je nakon čuvanja pripreme dostave.</p><?php endif;?>
